# map tool_use ids for bash commands running w07/w08/w09 to their results
uses={}
for line in open(p):
    try: d=json.loads(line)
    except: continue
    m=d.get('message',{})
    c=m.get('content')
    if not isinstance(c,list): continue
    for x in c:
        if x.get('type')=='tool_use' and x.get('name')=='Bash':
            cmd=x['input'].get('command','')
            for w in ('w07_admit','w08_templer','w09_templer'):
                if w in cmd and 'bash ' in cmd:
                    uses[x['id']]=w
        if x.get('type')=='tool_result' and x.get('tool_use_id') in uses:
            cont=x.get('content')
            txt=cont if isinstance(cont,str) else ' '.join(y.get('text','') for y in cont if isinstance(y,dict))
            print('=====',uses[x['tool_use_id']]); print(txt[:3000])
EOF

